mapper.select:
/*+ INDEX(a IDX_COST_ALLOCATION_PERIOD) INDEX(sc IDX_COST_CENTER_ID) */ WITH allocation_stats AS ( SELECT ALLOCATION_ID, COUNT(*) as target_center_count, SUM(ALLOCATED_AMOUNT) as total_allocated_amount FROM T_COST_ALLOCATION_DETAIL WHERE IS_DELETED = 0 GROUP BY ALLOCATION_ID ) SELECT /*+ CARDINALITY(a 1000) */ a.ALLOCATION_ID as allocationId, a.ALLOCATION_NO as allocationNo, a.ALLOCATION_PERIOD as allocationPeriod, a.SOURCE_CENTER_ID as sourceCenterId, sc.CENTER_NAME as sourceCenterName, a.ALLOCATION_METHOD as allocationMethod, a.TOTAL_AMOUNT as totalAmount, a.ALLOCATION_STATUS as allocationStatus, a.ALLOCATION_DATE as allocationDate, a.IS_GENERATE_VOUCHER as isGenerateVoucher, a.VOUCHER_ID as voucherId, a.REMARK as remark, a.CREATE_TIME as createTime, a.UPDATE_TIME as updateTime, NVL(d.target_center_count, 0) as targetCenterCount, NVL(d.total_allocated_amount, a.TOTAL_AMOUNT) as totalAllocatedAmount FROM T_COST_ALLOCATION a LEFT JOIN T_COST_CENTER sc ON a.SOURCE_CENTER_ID = sc.CENTER_ID AND sc.IS_DELETED = 0 LEFT JOIN allocation_stats d ON a.ALLOCATION_ID = d.ALLOCATION_ID WHERE a.IS_DELETED = 0
AND a.BOOK_ID = CAST(#{param.bookId} AS NUMBER)
AND a.TENANT_ID = CAST(#{param.tenantId} AS NUMBER)
AND a.ALLOCATION_PERIOD = #{param.allocationPeriod}
AND a.ALLOCATION_NO LIKE #{param.allocationNo} || '%'
AND a.SOURCE_CENTER_ID = CAST(#{param.sourceCostCenterId} AS NUMBER)
AND a.ALLOCATION_METHOD = #{param.allocationMethod}
AND a.ALLOCATION_STATUS = #{param.allocationStatus}
AND a.ALLOCATION_DATE >= TO_DATE(#{param.startDate}, 'YYYY-MM-DD')
AND a.ALLOCATION_DATE <= TO_DATE(#{param.endDate}, 'YYYY-MM-DD') + 1
AND a.TOTAL_AMOUNT >= #{param.minAmount}
AND a.TOTAL_AMOUNT <= #{param.maxAmount}
AND a.CREATOR = #{param.creator}
AND a.REMARK LIKE #{param.remark} || '%'
ORDER BY a.ALLOCATION_DATE DESC, a.ALLOCATION_ID DESC OFFSET #{offset} ROWS FETCH NEXT #{pageSize} ROWS ONLY

/*+ MATERIALIZE */ WITH period_filter AS ( SELECT ALLOCATION_ID, TOTAL_AMOUNT, ALLOCATION_STATUS, SOURCE_CENTER_ID, IS_GENERATE_VOUCHER FROM T_COST_ALLOCATION WHERE IS_DELETED = 0
AND BOOK_ID = CAST(#{param.bookId} AS NUMBER)
AND TENANT_ID = CAST(#{param.tenantId} AS NUMBER)
AND ALLOCATION_PERIOD = #{param.allocationPeriod}
) SELECT COUNT(1) as totalCount, COALESCE(SUM(TOTAL_AMOUNT), 0) as totalAmount, SUM(CASE WHEN ALLOCATION_STATUS = 1 THEN 1 ELSE 0 END) as pendingCount, SUM(CASE WHEN ALLOCATION_STATUS = 2 THEN 1 ELSE 0 END) as processingCount, SUM(CASE WHEN ALLOCATION_STATUS = 3 THEN 1 ELSE 0 END) as allocatedCount, SUM(CASE WHEN ALLOCATION_STATUS = 4 THEN 1 ELSE 0 END) as auditedCount, COUNT(DISTINCT SOURCE_CENTER_ID) as sourceCenterCount, SUM(CASE WHEN IS_GENERATE_VOUCHER = 1 THEN 1 ELSE 0 END) as voucherGeneratedCount FROM period_filter

/*+ LEADING(a v) USE_NL(a v) */ SELECT a.ALLOCATION_ID as allocationId, a.ALLOCATION_NO as allocationNo, a.TOTAL_AMOUNT as allocationAmount, v.VOUCHER_NO as voucherNo, v.VOUCHER_DATE as voucherDate, vs.COUNT as voucherEntryCount, vs.TOTAL_AMOUNT as voucherTotalAmount FROM T_COST_ALLOCATION a LEFT JOIN T_VOUCHER v ON a.VOUCHER_ID = v.VOUCHER_ID AND v.IS_DELETED = 0 LEFT JOIN ( SELECT VOUCHER_ID, COUNT(1) as COUNT, SUM(DEBIT_AMOUNT) as TOTAL_AMOUNT FROM T_VOUCHER_ENTRY WHERE IS_DELETED = 0 GROUP BY VOUCHER_ID ) vs ON v.VOUCHER_ID = vs.VOUCHER_ID WHERE a.IS_DELETED = 0 AND a.IS_GENERATE_VOUCHER = 1
AND a.ALLOCATION_PERIOD = #{param.allocationPeriod}
ORDER BY a.ALLOCATION_DATE DESC
